package top.iseason.bukkittemplate;

import org.bukkit.Bukkit;
import org.bukkit.event.HandlerList;
import org.bukkit.plugin.java.JavaPlugin;
import top.iseason.bukkittemplate.runtime.RuntimeManager;

import java.io.File;
import java.io.IOException;
import java.lang.reflect.Field;
import java.net.JarURLConnection;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.URL;
import java.util.jar.JarFile;

/**
 * bukkit绔富绫?鍏ュ彛
 */
public class BukkitTemplate extends JavaPlugin {

    public static RuntimeManager runtimeManager;
    private static JavaPlugin plugin = null;
    private static BukkitPlugin bukkitPlugin = null;

    /**
     * 鏋勯€犳柟娉曪紝璐熻矗涓嬭浇/娣诲姞渚濊禆锛屽苟鍚姩鎻掍欢
     */
    public BukkitTemplate() throws ClassNotFoundException, NoSuchFieldException, RuntimeException {
        plugin = this;
        runtimeManager = PluginYmlRuntime.parsePluginYml();
        bukkitPlugin = loadInstance();
    }

    public static RuntimeManager getRuntimeManager() {
        return runtimeManager;
    }

    /**
     * 鑾峰彇Bukkit鎻掍欢涓荤被
     *
     * @return Bukkit鎻掍欢涓荤被
     */
    public static JavaPlugin getPlugin() {
        return plugin;
    }

    /**
     * 鍔犺浇鎻掍欢涓荤被
     */
    private BukkitPlugin loadInstance() {
        Class<?> instanceClass = findInstanceClass();
        if (instanceClass == null) throw new RuntimeException("can not find plugin instance");
        try {
            BukkitPlugin instance;
            try {
                Field instanceField = instanceClass.getDeclaredField("INSTANCE");
                instanceField.setAccessible(true);
                instance = (BukkitPlugin) instanceField.get(null);
            } catch (Throwable e) {
                try {
                    instance = (BukkitPlugin) instanceClass.newInstance();
                } catch (Throwable ex) {
                    throw new RuntimeException("can not find plugin instance");
                }
            }
            return instance;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * 閬嶅巻瀵绘壘鎻掍欢鍏ュ彛绫?缁ф壙 BukkitPlugin
     *
     * @return 鎻掍欢鍏ュ彛绫?     */
    private Class<?> findInstanceClass() {
        Class<?> target = null;
        Class<BukkitPlugin> bukkitPluginClass = BukkitPlugin.class;
        ClassLoader classLoader = BukkitTemplate.class.getClassLoader();
        //鐚滄祴鍚?        String canonicalName = BukkitTemplate.class.getCanonicalName();
        String guessName = canonicalName.replace(".libs.core.BukkitTemplate", "") + "." + getPlugin().getName();
        try {
            target = Class.forName(guessName, false, classLoader);
            if (target != bukkitPluginClass && bukkitPluginClass.isAssignableFrom(target))
                return target;
        } catch (Exception ignored) {
        }
        // 閬嶅巻鏌ユ壘
        URL location = BukkitTemplate.class.getProtectionDomain().getCodeSource().getLocation();
        File srcFile;
        try {
            srcFile = new File(location.toURI());
        } catch (URISyntaxException e) {
            try {
                URI uri = ((JarURLConnection) location.openConnection()).getJarFileURL().toURI();
                srcFile = new File(uri);
            } catch (URISyntaxException | IOException ex) {
                srcFile = new File(location.getPath());
            }
        }
        try (JarFile jarFile = new JarFile(srcFile)) {
            //骞惰鏌ユ壘閫熷害鏇村揩
            target = jarFile.stream()
                    .parallel()
                    .map((it) -> {
                        String urlName = it.getName();
                        if (!urlName.endsWith(".class") || urlName.startsWith("META-INF")) {
                            return null;
                        }
                        try {
                            String className = urlName.replace('/', '.').substring(0, urlName.length() - 6);
                            return Class.forName(className, false, classLoader);
                        } catch (Throwable ignored) {
                            return null;
                        }
                    }).filter(it -> it != null &&
                            it != bukkitPluginClass &&
                            bukkitPluginClass.isAssignableFrom(it))
                    .findAny()
                    .orElse(null);
        } catch (IOException ignored) {
        }
        return target;
    }

    @Override
    public void onLoad() {
        try {
            bukkitPlugin.onLoad();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @Override
    public void onEnable() {
        try {
            bukkitPlugin.onEnable();
        } catch (Exception e) {
            e.printStackTrace();
        }
        Bukkit.getScheduler().runTaskAsynchronously(this, () -> bukkitPlugin.onAsyncEnable());
    }

    @Override
    public void onDisable() {
        try {
            bukkitPlugin.onDisable();
        } catch (Exception e) {
            e.printStackTrace();
        }
        Bukkit.getScheduler().cancelTasks(this);
        HandlerList.unregisterAll(this);
        DisableHook.disableAll();
    }
}

package top.iseason.bukkittemplate;

import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * 鍦ㄦ彃浠?onDisable 鏃惰嚜鍔ㄨ皟鐢?onDisable() 鏂规硶
 */
public final class DisableHook {

    private static final Queue<DisableTask> tasks = new ConcurrentLinkedQueue<>();

    /**
     * 杩愯鎵€鏈夋敞鍐岀殑浠诲姟锛屼細鍦ㄦ彃浠?onDisable 鏃惰嚜鍔ㄨ皟鐢?     */
    public static void disableAll() {
        for (DisableTask task : tasks) {
            try {
                task.onDisable();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        tasks.clear();
    }

    /**
     * 娣诲姞涓€涓湪鎻掍欢onDisable 鏃惰皟鐢ㄧ殑浠诲姟
     *
     * @param task 浠诲姟
     */
    public static void addTask(DisableTask task) {
        tasks.add(task);
    }

    public interface DisableTask {
        void onDisable();
    }
}

package top.iseason.bukkittemplate;

import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import top.iseason.bukkittemplate.runtime.ClassAppender;
import top.iseason.bukkittemplate.runtime.RuntimeManager;

import java.io.File;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.URLDecoder;
import java.util.List;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

public class PluginYmlRuntime {

    /**
     * 瑙ｆ瀽涓嬭浇plugin.yml涓殑渚濊禆
     */
    public static RuntimeManager parsePluginYml() throws RuntimeException {

        YamlConfiguration yml = null;
        // 涓轰粈涔堜笉鐢?classloader 鐨?getResource鍛紝鍥犱负鏌愪簺sb绯荤粺鎴栬€呮湇鍔＄浼氫贡鏀?        // 瀵艰嚧 getResource 鐨勫唴瀹归敊璇? 宸叉祴璇?Debian + CatServer
        String location = PluginYmlRuntime.class.getProtectionDomain().getCodeSource().getLocation().getPath();
        try (JarFile jarFile = new JarFile(URLDecoder.decode(location, "UTF-8"), false)) {
            JarEntry entry = jarFile.getJarEntry("plugin.yml");
            InputStream resource = jarFile.getInputStream(entry);
            yml = YamlConfiguration.loadConfiguration(new InputStreamReader(resource));
        } catch (Exception e) {
            e.printStackTrace();
        }
        if (yml == null) return null;
        ConfigurationSection libConfigs = yml.getConfigurationSection("runtime-libraries");
        if (libConfigs == null) return null;
        String folder = libConfigs.getString("libraries-folder");
        File parent = new File("libraries");
        if (folder != null) {
            if (folder.toLowerCase().startsWith("@plugin:")) {
                parent = new File(BukkitTemplate.getPlugin().getDataFolder(), folder.substring(8));
            } else {
                parent = new File(folder);
            }
        }
        List<String> repositories = libConfigs.getStringList("repositories");
        if (repositories.isEmpty()) {
            repositories.add("https://repo.maven.apache.org/maven2/");
        }
        List<String> libraries = libConfigs.getStringList("libraries");
        List<String> assemblyList = libConfigs.getStringList("assembly");
        List<String> excludes = libConfigs.getStringList("excludes");
        ClassAppender classAppender = new ClassAppender(PluginYmlRuntime.class.getClassLoader().getParent());
        RuntimeManager runtimeManager = new RuntimeManager(parent, classAppender, repositories, libraries, assemblyList, libConfigs.getBoolean("parallel"));
        runtimeManager.addExcludes(excludes);
        try {
            runtimeManager.injectTo(PluginYmlRuntime.class.getClassLoader());
        } catch (NoSuchFieldException | IllegalAccessException e) {
            e.printStackTrace();
            throw new RuntimeException("杩愯鐜娉ㄥ叆澶辫触!");
        }
        RuntimeManager.logger = BukkitTemplate.getPlugin().getLogger();
        runtimeManager.downloadAll();
        return runtimeManager;
    }
}

package top.iseason.bukkittemplate.runtime;

import top.iseason.bukkittemplate.runtime.loader.AppendableClassLoader;
import top.iseason.bukkittemplate.runtime.loader.IsolatedClassLoader;
import top.iseason.bukkittemplate.utils.ReflectionUtil;

import java.net.URL;

/**
 * 缁?ClassLoader 鍔ㄦ€佹坊鍔燯rl
 */
public class ClassAppender {

    private final AppendableClassLoader assemblyClassLoader;
    private final IsolatedClassLoader isolatedClassLoader;

    /**
     * @param parent 娉ㄥ叆渚濊禆鐨勭埗绫? 濡傛灉浣犳兂缁?A 娣诲姞杩愯鐜锛岄偅涔堝簲璇ヤ紶鍏?A.getParent()
     */
    public ClassAppender(ClassLoader parent) {
        AppendableClassLoader appendableClassLoader = new AppendableClassLoader(parent);
        IsolatedClassLoader isolatedClassLoader = new IsolatedClassLoader(appendableClassLoader);
        this.assemblyClassLoader = appendableClassLoader;
        this.isolatedClassLoader = isolatedClassLoader;
    }

    /**
     * @param assemblyClassLoader 蹇呴』鏄?URLClassLoader 鐨勫瓙绫?     * @param isolatedClassLoader
     */
    public ClassAppender(AppendableClassLoader assemblyClassLoader, IsolatedClassLoader isolatedClassLoader) {
        this.assemblyClassLoader = assemblyClassLoader;
        this.isolatedClassLoader = isolatedClassLoader;
    }

    /**
     * 灏哢Rl娣诲姞杩涙彃浠剁殑ClassLoader
     */
    public synchronized void addIsolatedURL(URL url) {
        if (url == null) return;
        isolatedClassLoader.addURL(url);
    }

    /**
     * 灏哢Rl娣诲姞杩涙彃浠剁殑ClassLoader
     */
    public synchronized void addAssemblyURL(URL url) {
        if (url == null) return;
        assemblyClassLoader.addURL(url);
    }

    /**
     * 灏嗚繍琛岀幆澧冩敞鍏ヨ嚦鏌愪釜ClassLoader涓?     *
     * @param classLoader 鐩爣ClassLoader
     */
    public void appendTo(ClassLoader classLoader) throws NoSuchFieldException, IllegalAccessException {
        ReflectionUtil.replaceFieldValue(ClassLoader.class, "parent", classLoader, isolatedClassLoader, true);
    }

    public AppendableClassLoader getAssemblyClassLoader() {
        return assemblyClassLoader;
    }

    public IsolatedClassLoader getIsolatedClassLoader() {
        return isolatedClassLoader;
    }
}

package top.iseason.bukkittemplate.runtime;

import java.io.File;
import java.util.LinkedList;
import java.util.List;
import java.util.logging.Logger;

/**
 * 杩愯鐜鏋勯€犲櫒
 */
public class RuntimeBuilder {

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private final List<String> assemblyDependencies = new LinkedList<>();
        private final List<String> excludeDependencies = new LinkedList<>();
        private ClassLoader classLoader;
        private File storagePath = new File("libraries");
        private List<String> repositories = new LinkedList<>();
        private List<String> dependencies = new LinkedList<>();
        private boolean isParallel = false;
        private Logger logger = Logger.getLogger(RuntimeManager.class.getSimpleName());

        /**
         * 璁剧疆渚濊禆鍌ㄥ瓨璺緞
         */
        public Builder storagePath(File storagePath) {
            this.storagePath = storagePath;
            return this;
        }

        /**
         * 璁剧疆闇€瑕?Runtime 鐨刢lassloader
         */
        public Builder classLoader(ClassLoader classLoader) {
            this.classLoader = classLoader;
            return this;
        }

        /**
         * 灏嗗綋鍓峜lass鐨凜lassLoader璁剧疆涓洪渶瑕乺untime鐨凜lassLoader
         */
        public Builder currentClassLoader() {
            this.classLoader = this.getClass().getClassLoader();
            return this;
        }

        /**
         * 娣诲姞渚濊禆浠撳簱锛屾寜娣诲姞椤哄簭涓嬭浇
         */
        public Builder repository(String repository) {
            if (!repository.endsWith("/")) repository = repository + "/";
            this.repositories.add(repository);
            return this;
        }

        /**
         * 娣诲姞渚濊禆浠撳簱锛屾寜娣诲姞椤哄簭涓嬭浇
         */
        public Builder repositories(List<String> repositories) {
            this.repositories = repositories;
            return this;
        }

        /**
         * 娣诲姞渚濊禆<p>
         * 鏍煎紡涓?group:artifact:version<p>
         * 鎴?group:artifact:version,depth<p>
         * 鍏朵腑鐨?depth 琛ㄧず渚濊禆鏍戝眰鏁帮紝榛樿2
         */
        public Builder dependency(String dependency) {
            if (RuntimeManager.checkLibraryIllegal(dependency)) {
                throw new IllegalArgumentException(dependency + " was not a illegal dependency");
            }
            this.dependencies.add(dependency);
            return this;
        }

        /**
         * 娣诲姞渚濊禆
         */
        public Builder dependencies(List<String> dependencies) {
            this.dependencies = dependencies;
            return this;
        }

        /**
         * 涓嬭浇渚濊禆鐨勮繃绋嬶紝姝や緷璧栧皢涓嶄粠闅旂鐨凜lassLoader涓鍙栵紝鑰屾槸鎸夌収鍙屼翰濮旀淳鐨勬柟寮忚鍙?p>
         * 寤鸿灏嗕竴浜涙棩蹇桝PI娣诲姞杩涘幓<p>
         * 鏍煎紡: group:artifact
         */
        public Builder assembly(String dependency) {
            this.assemblyDependencies.add(dependency);
            return this;
        }

        /**
         * 涓嬭浇渚濊禆鏃朵細瑙ｆ瀽渚濊禆鐨勪緷璧栵紝鍙兘鍑虹幇涓€浜涗笉鎯宠鐨勪緷璧栵紝鍦ㄦ澹版槑浠ユ帓闄?p>
         * 寤鸿灏嗕竴浜涙棩蹇桝PI娣诲姞杩涘幓<p>
         * 鏍煎紡: group:artifact
         */
        public Builder exclude(String dependency) {
            this.excludeDependencies.add(dependency);
            return this;
        }

        /**
         * 璁剧疆骞惰涓嬭浇渚濊禆
         */
        public Builder parallel() {
            this.isParallel = true;
            return this;
        }

        /**
         * 璁剧疆 logger null 涓嶈褰曟棩蹇?         */
        public Builder logger(Logger logger) {
            this.logger = logger;
            return this;
        }

        /**
         * 鏋勫缓杩愯鐜骞朵笅杞戒緷璧?         *
         * @return 杩愯鐜绠＄悊鑰?         */
        public RuntimeManager build() throws NoSuchFieldException, IllegalAccessException, IllegalArgumentException {
            if (classLoader == null) throw new IllegalArgumentException("classLoader can not be null");
            if (repositories == null) throw new IllegalArgumentException("repositories can not be null");
            if (dependencies == null) throw new IllegalArgumentException("dependencies can not be null");
            if (assemblyDependencies == null)
                throw new IllegalArgumentException("assemblyDependencies can not be null");
            if (excludeDependencies == null) throw new IllegalArgumentException("excludeDependencies can not be null");
            if (storagePath == null) storagePath = new File("libraries");
            if (repositories.isEmpty()) throw new IllegalArgumentException("classLoader can not be null");
            RuntimeManager.logger = this.logger;
            ClassAppender classAppender = new ClassAppender(classLoader.getParent());
            RuntimeManager runtimeManager = new RuntimeManager(storagePath, classAppender, repositories, dependencies, assemblyDependencies, isParallel);
            runtimeManager.addExcludes(excludeDependencies);
            runtimeManager.injectTo(classLoader);
            runtimeManager.downloadAll();
            return runtimeManager;
        }
    }
}

