    /**
     * 娣诲姞闇€瑕佺殑渚濊禆
     *
     * @param dependency 渚濊禆, 灏嗕細涓嬭浇渚濊禆鐨勫瓙渚濊禆(2灞?
     * @return 鑷韩
     */
    public RuntimeManager addDependency(String dependency) {
