package top.iseason.bukkittemplate.runtime.loader;

import java.net.URL;
import java.net.URLClassLoader;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * <p>鎻掍欢鑷畾涔夌殑鍔犺浇鍣紝鐢ㄤ簬闅旂渚濊禆</p>
 * <p>鏈珻lassLoader灏嗕紭鍏堝姞杞絬rls涓湁鐨刢lass锛岃€屼笉鏄弻浜插鎵?/p>
 */
public class IsolatedClassLoader extends URLClassLoader {
    /**
     * 鑷敱娣诲姞榛戝悕鍗?     */
    public static final Set<String> BLACK_LIST = new HashSet<>();

    public IsolatedClassLoader(ClassLoader parent) {
        this(new URL[0], parent);
    }

    public IsolatedClassLoader(URL[] urls, ClassLoader parent) {
        super(urls, parent);
    }


    public static void addBlackList(Class<?> clazz) {
        BLACK_LIST.add(clazz.getName());
        List<String> subClasses = Arrays.stream(clazz.getDeclaredClasses()).map(Class::getName).collect(Collectors.toList());
        BLACK_LIST.addAll(subClasses);
    }

    @Override
    protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
        synchronized (getClassLoadingLock(name)) {
            Class<?> loadedClass = findLoadedClass(name);
            if (loadedClass == null) {
                String path = name.replace('.', '/').concat(".class");
                URL resource = findResource(path);
                // 璇诲彇渚濊禆
                if (resource != null && !BLACK_LIST.contains(name)) {
                    try {
                        loadedClass = findClass(name);
                    } catch (ClassNotFoundException ignored) {
                    }
                }
                // 涓嶆槸渚濊禆
                if (loadedClass == null) {
                    ClassLoader parent = getParent();
                    if (parent != null) {
                        loadedClass = parent.loadClass(name);
                    }
                }
            }
            if (resolve) {
                resolveClass(loadedClass);
            }
            return loadedClass;
        }
    }

    @Override
    public void addURL(URL url) {
        super.addURL(url);
    }
}

package top.iseason.bukkittemplate.utils;

public class JavaVersion {
    private static int version;

    static {
        String versionString = System.getProperty("java.version");
        int indexOf = versionString.indexOf('.');
        try {
            if (indexOf > 0) {
                String substring = versionString.substring(0, indexOf);
                if (substring.equals("1")) {
                    int indexOf1 = versionString.indexOf('.', indexOf + 1);
                    version = Integer.parseInt(versionString.substring(indexOf + 1, indexOf1));
                } else {
                    version = Integer.parseInt(substring);
                }
            } else {
                version = Integer.parseInt(versionString);
            }
        } catch (Exception e) {
            version = 8;
        }
    }

    public static boolean isGreaterOrEqual(int version) {
        return JavaVersion.version >= version;
    }
}

package top.iseason.bukkittemplate.utils;

import sun.misc.Unsafe;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.reflect.Field;

// 鍙嶅皠宸ュ叿
public class ReflectionUtil {
    private static final Unsafe unsafe;
    private static final MethodHandles.Lookup lookup;
    private static final MethodHandle getDeclaredFields0;

    static {
        try {
            Field f = Unsafe.class.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            unsafe = (Unsafe) f.get(null);
            //灏嗗瓙渚濊禆濉叆鎻掍欢classloader
            Field lookupField = MethodHandles.Lookup.class.getDeclaredField("IMPL_LOOKUP");
            lookup = (MethodHandles.Lookup) unsafe.getObject(unsafe.staticFieldBase(lookupField), unsafe.staticFieldOffset(lookupField));
            getDeclaredFields0 = lookup.findVirtual(Class.class, "getDeclaredFields0", MethodType.methodType(Field[].class, boolean.class));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public static MethodHandle getMethod(Class<?> clazz, String name, MethodType methodType) throws NoSuchMethodException, IllegalAccessException {
        return lookup.findVirtual(clazz, name, methodType);
    }

    public static MethodHandle getStaticMethod(Class<?> clazz, String name, MethodType methodType) throws NoSuchMethodException, IllegalAccessException {
        return lookup.findStatic(clazz, name, methodType);
    }

    /**
     * 鏇挎崲 object 涓殑鏌愪竴涓彉閲?     *
     * @param target  琚浛鎹㈢殑瀵硅薄
     * @param field   琚浛鎹㈢殑鎴愬憳
     * @param value   鏇挎崲鐨勫€?     * @param isForce 鏄惁浣跨敤 Unsafe 鏃犺璁块棶鏉冮檺寮哄埗鏇挎崲
     */
    public static void replaceObject(Object target, Field field, Object value, boolean isForce, boolean isVolatile) throws IllegalAccessException {
        if (isForce) {
            if (isVolatile)
                unsafe.putObjectVolatile(target, unsafe.objectFieldOffset(field), value);
            else
                unsafe.putObject(target, unsafe.objectFieldOffset(field), value);
        } else {
            field.setAccessible(true);
            field.set(target, value);
            field.setAccessible(false);
        }

    }

    /**
     * 寮哄埗鏇挎崲鏌愪釜绫讳腑鐨勬垚鍛?     *
     * @param clazz      鎴愬憳澹版槑鐨凜lass
     * @param fieldName  鎴愬憳鍚?     * @param target     鏇挎崲鐨勫璞?     * @param value      鏇挎崲鐨勫€?     * @param isVolatile 鎴愬憳鏄惁鏄?Volatile 淇グ鐨?     * @throws NoSuchFieldException   鎵句笉鍒拌鎴愬憳
     * @throws IllegalAccessException 鏇挎崲澶辫触
     */
    public static void replaceFieldValue(
            Class<?> clazz,
            String fieldName,
            Object target,
            Object value,
            boolean isVolatile) throws NoSuchFieldException, IllegalAccessException {
        Field parentField = findField(clazz, fieldName);
        replaceObject(target, parentField, value, true, isVolatile);
    }

    /**
     * <p>寮哄埗鑾峰彇鏌愪釜绫讳腑鐨勬煇涓悕瀛楃殑Field</p>
     * <p>鏃犺璁块棶鏉冮檺瀹夊叏妯″潡</p>
     *
     * @param clazz     鏌ユ壘鐨勭被
     * @param fieldName 鎴愬憳鍚嶅瓧
     * @return 鎵惧埌鐨凢ield
     * @throws NoSuchFieldException 鎵句笉鍒版敼鍚嶅瓧鐨凢ield
     */
    public static Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        Field field = null;
        try {
            field = clazz.getField(fieldName);
        } catch (NoSuchFieldException e1) {
            try {
                field = clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e2) {
                try {
                    Field[] fields = (Field[]) getDeclaredFields0.invoke(clazz, false);
                    for (Field f : fields) {
                        if (fieldName.equals(f.getName())) {
                            field = f;
                            break;
                        }
                    }
                } catch (Throwable e3) {
                    throw new NoSuchFieldException();
                }
            }
        }
        return field;
    }

}

package top.iseason.bukkittemplate.command

import org.bukkit.Bukkit
import org.bukkit.command.PluginCommand
import org.bukkit.command.SimpleCommandMap
import org.bukkit.permissions.Permission
import org.bukkit.plugin.Plugin
import org.bukkit.plugin.SimplePluginManager
import top.iseason.bukkittemplate.BukkitTemplate
import top.iseason.bukkittemplate.DisableHook
import top.iseason.bukkittemplate.utils.bukkit.MessageUtils.toColor
import java.lang.reflect.Constructor
import java.util.*
import java.util.stream.Collectors

/**
 * 鎵€鏈夊懡浠ょ殑绠＄悊绫? */
@Suppress("unused")
object CommandHandler {
    /**
     * 鍌ㄥ瓨鍛戒护鏉冮檺
     */
    private val commandPermissions = mutableSetOf<Permission>()

    /**
     * 鎵€鏈夋敞鍐岀殑鍛戒护
     */
    private val registeredCommands = mutableListOf<PluginCommand>()
    private val simpleCommandMap: SimpleCommandMap
    private val pluginCommandConstructor: Constructor<PluginCommand> = getPluginCommandConstructor()

    init {
        val simplePluginManager = Bukkit.getServer().pluginManager as SimplePluginManager
        val commandMapField = SimplePluginManager::class.java.getDeclaredField("commandMap")
        commandMapField.isAccessible = true
        simpleCommandMap = commandMapField.get(simplePluginManager) as SimpleCommandMap
        DisableHook.addTask { onDisable() }
    }

    // PluginCommand鍘熸湰鍙兘閫氳繃plugin.yml涓０鏄庣殑鍛戒护鍒涘缓锛屾湁鐐硅嚜绉侊紝涔栦箹寮€鏀惧惂
    private fun getPluginCommandConstructor(): Constructor<PluginCommand> {
        val constructor = PluginCommand::class.java.getDeclaredConstructor(String::class.java, Plugin::class.java)
        constructor.isAccessible = true
        return constructor
    }

    /**
     * 灏嗗懡浠よ妭鐐规敞鍐屼负鏍瑰懡浠?     */
    fun register(commandNode: CommandNode) {
        require(commandNode.parent == null) { "鍙兘涓烘牴鍛戒护娉ㄥ唽!" }
        val pluginCommand =
            pluginCommandConstructor.newInstance(commandNode.name, BukkitTemplate.getPlugin()) as PluginCommand
        if (commandNode.alias != null) {
            pluginCommand.aliases = Arrays.stream(commandNode.alias).collect(Collectors.toList())
        }
        if (commandNode.description != null) {
            pluginCommand.description = commandNode.description!!
        }
        pluginCommand.permissionMessage = commandNode.noPermissionMessage?.toColor()
        pluginCommand.setExecutor(commandNode)
        pluginCommand.tabCompleter = commandNode
        simpleCommandMap.register(BukkitTemplate.getPlugin().name, pluginCommand)
        commandPermissions.add(commandNode.permission)
        registeredCommands.add(pluginCommand)
    }

    // 娉ㄩ攢鏍瑰懡浠?    fun unregister(commandNode: CommandNode) {
        require(commandNode.parent == null) { "闈炴牴鍛戒护涓嶉渶瑕佹敞閿€!" }
        Bukkit.getServer().getPluginCommand(commandNode.name)?.unregister(simpleCommandMap)
    }

    /**
     * 娉ㄩ攢鎵€鏈夊凡缁忔敞鍐岀殑鎻掍欢
     */
    @JvmStatic
    fun unregisterAll() {
        for (registeredCommand in registeredCommands) {
            registeredCommand.unregister(simpleCommandMap)
        }
    }

    /**
     * 娣诲姞涓€涓懡浠ゆ潈闄愯繘鍏ョ紦瀛橈紝鐢ㄤ簬娉ㄩ攢
     */
    fun addPermissions(perm: Permission) {
        commandPermissions.add(perm)
    }

    /**
     * 娓呴櫎鎵€鏈夊懡浠ょ殑鏉冮檺
     */
    fun clearPermissions() {
        for (pluginPermission in commandPermissions) {
            Bukkit.getPluginManager().removePermission(pluginPermission)
        }
    }

    /**
     * 姝ｇ‘鍦版敞閿€鎵€鏈夊懡浠?     */
    @JvmStatic
    fun onDisable() {
        clearPermissions()
        unregisterAll()
    }

    /**
     * 鏇存柊娉ㄥ唽鐨勫懡浠や互鏀寔tab
     */
    @JvmStatic
    fun updateCommands() {
        try {
            Bukkit.getServer().apply {
                javaClass.getDeclaredMethod("syncCommands").invoke(this)
            }
        } catch (_: Exception) {
        }
    }

}

/**
 * 鍒涘缓鍛戒护鏍硅妭鐐? * @param name 鍚嶅瓧
 * @param modify 瀵硅妭鐐圭殑淇敼
 * @return 鍒涘缓鐨勮妭鐐? */
fun command(name: String, modify: (CommandNode.() -> Unit)? = null): CommandNode {
    val commandNode = node(name, modify)
    CommandHandler.register(commandNode)
    return commandNode
}

/**
 * 鍒涘缓鍛戒护鏍硅妭鐐? * @param name 鍚嶅瓧
 * @param modify 瀵硅妭鐐圭殑淇敼
 * @return 鍒涘缓鐨勮妭鐐? */
fun command(node: CommandNode, modify: (CommandNode.() -> Unit)? = null): CommandNode {
    modify?.invoke(node)
    CommandHandler.register(node)
    return node
}

/**
 * 涓鸿妭鐐规坊鍔犲瓙鑺傜偣
 * @param name 鍚嶅瓧
 * @param modify 瀵硅妭鐐圭殑淇敼
 * @return 鍒涘缓鐨勮妭鐐? */
fun CommandNode.node(name: String, modify: (CommandNode.() -> Unit)? = null): CommandNode {
    val commandNode = top.iseason.bukkittemplate.command.node(name, modify)
    this.addSubNode(commandNode)
    return commandNode
}

/**
 * 鍒涘缓涓€涓病鏈変笂涓嬪叧绯荤殑鑺傜偣
 * 浣跨敤CommandNode::addSubNode娣诲姞瀛愯妭鐐规垨灏嗚嚜宸辨坊鍔犲埌鏌愪釜鐖惰妭鐐逛腑
 *
 * @param name 鍚嶅瓧
 * @param modify 瀵硅妭鐐圭殑淇敼
 * @return 鍒涘缓鐨勮妭鐐? */
fun node(name: String, modify: (CommandNode.() -> Unit)? = null): CommandNode {
    val commandNode = CommandNode(name)
    modify?.let { it(commandNode) }
    return commandNode
}

/**
 * 涓鸿妭鐐规坊鍔犲瓙鑺傜偣
 * @param name 鍚嶅瓧
 * @param modify 瀵硅妭鐐圭殑淇敼
 * @return 鍒涘缓鐨勮妭鐐? */
fun CommandNode.node(node: CommandNode): CommandNode {
    this.addSubNode(node)
    return node
}

/**
 * 璁剧疆鍛戒护鎵ц鑰? */
fun CommandNode.executor(onExecute: CommandNodeExecutor? = null) {
    this.onExecute = onExecute
}

/**
 * 娣诲姞涓€涓弬鏁? */
fun CommandNode.param(
    placeholder: String,
    suggest: Collection<String>? = null,
    suggestRuntime: Param.RuntimeSuggestParams? = null
) {
    params = params.toMutableList().apply { add(Param(placeholder, suggest, suggestRuntime)) }
}

package top.iseason.bukkittemplate.command

import org.bukkit.Bukkit
import org.bukkit.command.Command
import org.bukkit.command.CommandExecutor
import org.bukkit.command.CommandSender
import org.bukkit.command.TabExecutor
import org.bukkit.entity.Player
import org.bukkit.permissions.Permission
import org.bukkit.permissions.PermissionDefault
import top.iseason.bukkittemplate.BukkitTemplate
import top.iseason.bukkittemplate.debug.SimpleLogger
import top.iseason.bukkittemplate.utils.bukkit.MessageUtils.sendColorMessage
import top.iseason.bukkittemplate.utils.bukkit.MessageUtils.sendColorMessages
import top.iseason.bukkittemplate.utils.other.submit
import java.util.*

@Suppress("MemberVisibilityCanBePrivate", "unused")
open class CommandNode(
    /**
     * 鑺傜偣鍚嶇О
     */
    val name: String,
    /**
     * 鑺傜偣鍒悕
     */
    var alias: Array<String>? = null,
    /**
     * 鎻忚堪
     */
    var description: String? = null,
    /**
     * 榛樿鎵ц鏉冮檺
     */
    var default: PermissionDefault = PermissionDefault.TRUE,
    /**
     * 鏄惁寮傛鎵ц
     */
    var async: Boolean = false,
    /**
     * 鍙傛暟鍒楄〃
     */
    var params: List<Param> = listOf(),
    /**
     * 鏄惁浠呯帺瀹舵墽琛?     */
    var isPlayerOnly: Boolean = false,
    /**
     * 鍛戒护鎵ц
     */
    open var onExecute: CommandNodeExecutor? = null
) : CommandExecutor, TabExecutor {
    var permission: Permission =
        Permission("${BukkitTemplate.getPlugin().name.lowercase()}.$name", default)

    /**
     * 鑾峰彇鐖惰妭鐐?     */
    var parent: CommandNode? = null
        private set(value) {
            field = value
            if (field != null) {
                val str = "${field!!.permission.name}.$name".lowercase(Locale.ENGLISH)
                val par = "${field!!.permission.name}.*".lowercase(Locale.ENGLISH)
                var parentPerm = Bukkit.getPluginManager().getPermission(par)
                if (parentPerm == null) {
                    parentPerm = Permission(par, PermissionDefault.OP)
                    Bukkit.getPluginManager().addPermission(parentPerm)
                    CommandHandler.addPermissions(parentPerm)
                }
                permission = Permission(str, default)
                try {
                    Bukkit.getPluginManager().addPermission(permission)
                } catch (e: Exception) {
                    permission = Bukkit.getPluginManager().getPermission(permission.name)!!
                }
                permission.addParent(parentPerm, true)
            }
        }

    /**
     * 瀛愯妭鐐瑰悕绉伴泦鍚?     */
    val subNodeKeys = mutableListOf<String>()

    /**
     * 瀛愯妭鐐规槧灏勶紝鍏ㄥ皬鍐?     */
    val subNodesInsensitive = mutableMapOf<String, CommandNode>()

    /**
     * 鍙傛暟绫诲瀷鍜屽缓璁弬鏁?     */
    var noPermissionMessage: String? = CommandNode.noPermissionMessage

    /**
     * 娣诲姞瀛愯妭鐐?     */
    fun addSubNode(node: CommandNode) {
        if (parent == null && Bukkit.getPluginManager().getPermission(permission.name) == null) {
            Bukkit.getPluginManager().addPermission(permission)
        }
        subNodeKeys += node.name
        subNodesInsensitive[node.name.lowercase()] = node
        node.parent = this
        CommandHandler.addPermissions(node.permission)
        node.alias?.forEach {
            subNodeKeys += it
            subNodesInsensitive[it.lowercase()] = node
        }
    }

    /**
     * 鑾峰彇瀛愯妭鐐?澶у皬鍐欎笉鏁忔劅
     * @return null if not exists
     */
    fun getSubNode(arg: String) = subNodesInsensitive[arg.lowercase()]

    /**
     * 鑾峰彇璇ュ懡浠ゅ彂閫佽€呭彲瑙佺殑瀛愯妭鐐?     * @return null if not exists
     */
    fun getSubNode(arg: String, sender: CommandSender): CommandNode? {
        val commandNode = getSubNode(arg) ?: return null
        if (!commandNode.canUse(sender)) return null
        return commandNode
    }

    /**
     * 鑾峰彇鍛戒护鎵ц鑰呭彲瑙佺殑鎵€鏈夊瓙鑺傜偣
     */
    fun getSubNodes(sender: CommandSender): Set<CommandNode> {
        val set = mutableSetOf<CommandNode>()
        for (value in subNodesInsensitive.values) {
            if (!value.canUse(sender)) continue
            set.add(value)
        }
        return set
    }

    /**
     * 鑾峰彇鏍硅妭鐐?     */
    fun getRootNode(): CommandNode = parent?.getRootNode() ?: this

    /**
     * 鍒ゆ柇鍛戒护鎵ц鑰呮槸鍚﹀彲鐢?     */
    fun canUse(sender: CommandSender): Boolean {
        return sender.hasPermission(permission)
    }

    /**
     * 鑾峰彇鐢ㄦ埛鏈夋潈闄愮殑瀛愰敭鍚嶇О
     */
    fun getKeys(sender: CommandSender): MutableList<String> {
        return subNodeKeys.filter {
            getSubNode(it)?.canUse(sender) == true
        }.toMutableList()

    }

    /**
     * 鍦ㄥ懡浠ゆ墽琛岃€呮寜涓婽ab鏃惰皟鐢紝鍙皟鐢ㄦ牴鑺傜偣
     */
    override fun onTabComplete(
        sender: CommandSender,
        command: Command,
        label: String,
        args: Array<String>
    ): List<String>? {
        require(parent == null) { "鍙湁鏍硅妭鐐规墠鑳戒娇鐢? }
        var node: CommandNode = this
        // 涓嶅畬鏁村弬鏁?        var incomplete = ""
        var deep = 0
        for ((index, arg) in args.withIndex()) {
            val subNode = if (arg.isBlank()) null else node.getSubNode(arg, sender)
            if (subNode == null) {
                incomplete = arg
                deep = index
                break
            }
            node = subNode
        }
        val keys = node.getKeys(sender)
        if (keys.isEmpty() && node.params.isNotEmpty()) {
            val last = args.last()
            val param = node.params.getOrNull(args.size - deep - 1) ?: return null
            return (param.suggestRuntime?.getParams(sender) ?: param.suggest)?.filter {
                it.startsWith(last, true)
            }
        }
        return keys.filter { it.startsWith(incomplete, true) }
    }

    /**
     * 鎵ц鍛戒护锛岀敱鏍硅妭鐐硅礋璐ｈ浆鍙戯紝鏈€缁堣皟鐢?onExecute 鏂规硶
     */
    override fun onCommand(sender: CommandSender, command: Command, label: String, args: Array<String>): Boolean {
        require(parent == null) { "鍙湁鏍硅妭鐐规墠鑳戒娇鐢? }
        if (!canUse(sender)) {
            sender.sendColorMessage(noPermissionMessage?.replace("%permission%", permission.name))
            return true
        }
        var node: CommandNode = this
        var deep = 0
        for (arg in args) {
            node = node.getSubNode(arg)?.apply {
                if (!canUse(sender)) {
                    sender.sendColorMessage(
                        noPermissionMessage?.replace("%permission%", permission.name),
                        SimpleLogger.prefix
                    )
                    return true
                }
            } ?: break
            deep++
        }
        if (node.subNodeKeys.isNotEmpty() && node.onExecute == null) {
            node.showUsage(sender)
            return true
        }
        val params = args.copyOfRange(deep, args.size)
        if (node.onExecute == null) return true
        if (node.isPlayerOnly && sender !is Player) {
            sender.sendColorMessage("&c璇ュ懡浠や粎闄愬埗鐜╁浣跨敤!")
            return true
        }
        submit(async = node.async) {
            try {
                node.onExecute!!.accept(Params(params, node), sender)
            } catch (e: ParmaException) {
                //鍙傛暟閿欒鐨勬彁绀?                if (e.paramAdopter != null) {
                    sender.sendColorMessage(e.paramAdopter.errorMessage.format(e.arg))
                } else {
                    val message = e.message ?: return@submit
                    sender.sendColorMessage(message)
                }
            }
        }
        return true
    }

    /**
     * 灞曠ず鐢ㄦ硶
     */
    fun showUsage(sender: CommandSender) {
        val list = mutableListOf<String>()
        if (usageHeader != null) list.add(usageHeader!!)
        val subs = getSubNodes(sender)
        if (subs.isEmpty() && params.isEmpty()) return
        for (key in subs) {
            list.add(usage.format(key.name, key.getSuggest(), key.description ?: ""))
        }
        if (subs.isEmpty() && params.isNotEmpty()) {
            list.add(usage.format(getWholeCommand(), getSuggest(), description ?: ""))
        }
        if (usageFooter != null) list.add(usageFooter!!)
        sender.sendColorMessages(list)
    }

    /**
     * 娉ㄥ唽鑺傜偣
     */
    fun registerAsRoot() = CommandHandler.register(this)

    /**
     * 鑾峰彇瀹屾暣鐨勫懡浠ょ粨鏋?     */
    fun getWholeCommand(): String {
        var node = this
        var command = name
        while (node.parent != null) {
            command = "${node.parent!!.name} $command"
            node = node.parent!!
        }
        return command
    }

    /**
     * 鑾峰彇鍛戒护鐨勫缓璁?     */
    fun getSuggest(): String {
        val sb = StringBuilder()
        for (pa in params) {
            sb.append(pa.placeholder).append(" ")
        }
        return sb.toString()
    }

    companion object {

        // 娌℃湁鏉冮檺鐨勬秷鎭?        var noPermissionMessage: String? = "&c浣犳病鏈夎鍛戒护鐨勬潈闄? &7%permission%"

        // 浣跨敤鎻愮ず娑堟伅澶?        var usageHeader: String? = "  &7=======> &d${BukkitTemplate.getPlugin().name} &7<======="

        /**
         * 鍛戒护鐢ㄦ硶
         */
        var usage: String = "&7 - &6%s &a%s &7%s"

        // 浣跨敤鎻愮ず娑堟伅灏鹃儴
        var usageFooter: String? = " "
    }

}

@file:Suppress("UNCHECKED_CAST", "DEPRECATION")

package top.iseason.bukkittemplate.command

import org.bukkit.Bukkit
import org.bukkit.OfflinePlayer
import org.bukkit.entity.Player
import org.bukkit.potion.PotionEffectType
import java.util.*
import kotlin.reflect.KClass

/**
 * 鍙傛暟閫傞厤鍣紝璐熻矗灏嗗弬鏁拌浆涓哄搴旂被鐨勫璞? */
@Suppress("unused")
open class ParamAdopter<T : Any>(
    val type: KClass<T>,
    var errorMessage: String = "Param %s is not exist",
    val onCast: ParamTransform<T>
) {
    fun interface ParamTransform<T> {
        fun onCast(param: String): T?
    }

    companion object {
        private val paramsAdopter = mutableMapOf<KClass<*>, ParamAdopter<*>>()

        init {
            setDefaultParams()
        }

        /**
         * 娣诲姞涓€涓弬鏁伴€傞厤鍣?         */
        fun addTypeParam(paramAdopter: ParamAdopter<*>) {
            paramsAdopter[paramAdopter.type] = paramAdopter
        }

        /**
         * 鑾峰彇璐熻矗杞崲鏌愮被鍨嬬殑閫傞厤鍣?         */
        fun getTypeParam(clazz: KClass<*>) = paramsAdopter[clazz]

        /**
         * 鍒犻櫎鏌愮被鍨嬬殑鍙傛暟閫傞厤鍣?         */
        fun removeType(type: KClass<*>) = paramsAdopter.remove(type)

        /**
         * 鑾峰彇杞崲鍚庣殑鍙傛暟锛?         * @return 杞崲鍚庣殑鍙傛暟锛屼笉瀛樺湪鍒檔ull
         */
        fun <T> getOptionalTypedParam(clazz: KClass<*>, paramStr: String): T? {
            val typeParam = paramsAdopter[clazz]
            //鍖归厤鎵€鏈夋灇涓?            if (typeParam == null && clazz.java.isEnum) {
                return kotlin.runCatching {
                    java.lang.Enum.valueOf(
                        clazz.java as Class<out Enum<*>>,
                        paramStr.uppercase()
                    )
                }.getOrNull() as? T
            }
            if (typeParam == null) throw ParmaException("Param Type is not exist!")
            return typeParam.onCast.onCast(paramStr) as? T
        }

        /**
         * 鑾峰彇杞崲鍚庣殑鍙傛暟锛?         * @return 杞崲鍚庣殑鍙傛暟锛屼笉瀛樺湪鍒?         * @throws ParmaException
         */
        fun <T> getTypedParam(clazz: KClass<*>, paramStr: String): T {
            return getOptionalTypedParam(clazz, paramStr) ?: throw ParmaException(paramStr, paramsAdopter[clazz])
        }
    }

    /**
     * 娉ㄥ唽鏈€傞厤鍣?     */
    fun register() = addTypeParam(this)
}

/**
 * 榛樿鎻愪緵鐨勫弬鏁? */
private fun setDefaultParams() {
    ParamAdopter(Player::class, errorMessage = "&7鐜╁ &c%s &7涓嶅瓨鍦?") {
        if (it.length == 36) {
            runCatching { Bukkit.getPlayer(UUID.fromString(it)) }.getOrNull()
        } else Bukkit.getPlayerExact(it)
    }.register()
    ParamAdopter(OfflinePlayer::class, errorMessage = "&7鐜╁ &c%s &7涓嶅瓨鍦?") {
        var player: OfflinePlayer? = Bukkit.getOfflinePlayer(it)
        if (!player!!.hasPlayedBefore()) {
            player = runCatching {
                val offlinePlayer = Bukkit.getOfflinePlayer(UUID.fromString(it))
                if (offlinePlayer.hasPlayedBefore()) offlinePlayer else null
            }.getOrNull()
        }
        player
    }.register()
    ParamAdopter(Int::class, errorMessage = "&c%s &7涓嶆槸涓€涓湁鏁堢殑鏁存暟") {
        runCatching { it.toInt() }.getOrNull()
    }.register()
    ParamAdopter(Double::class, errorMessage = "&c%s &7涓嶆槸涓€涓湁鏁堢殑灏忔暟") {
        runCatching { it.toDouble() }.getOrNull()
    }.register()
    ParamAdopter(String::class) { it }.register()
    ParamAdopter(UUID::class, errorMessage = "&c%s &7涓嶆槸涓€涓湁鏁堢殑UUID") {
        runCatching { UUID.fromString(it) }.getOrNull()
    }.register()
    ParamAdopter(
        PotionEffectType::class,
        "&c%s &7涓嶆槸涓€涓湁鏁堢殑鑽按绉嶇被"
    ) {
        PotionEffectType.getByName(it)
    }.register()

}

