        }
        isConnecting = false
    }

    /**
     * 鍏抽棴鏁版嵁搴?     */
    fun closeDB() {
        if (!isConnected) return
        runCatching {
            ds?.close()
            TransactionManager.closeAndUnregister(connection)
            isConnected = false
        }.getOrElse { it.printStackTrace() }
    }

    /**
     * 鍒濆鍖栬〃
