    fun initTables(vararg tables: Table) {
        if (!isConnected) return
        this.tables = tables
        runCatching {
            dbTransaction {
                SchemaUtils.create(*tables)
//                SchemaUtils.createMissingTablesAndColumns(tables = tables, inBatch = false, withLogs = false)
            }
        }.getOrElse { it.printStackTrace() }
    }

