package top.iseason.bukkittemplate.config.type

import java.lang.reflect.Field
import java.util.*
import java.util.concurrent.CopyOnWriteArrayList

/**
 * 涓€鑸琇ist : CopyOnWriteArrayList銆丩inkedList銆丄rrayList銆丼tack
 */
object ListType : ConfigType {
    override fun checkType(clazz: Class<*>): Boolean {
        return List::class.java.isAssignableFrom(clazz)
    }

    override fun read(obj: Any, field: Field): Any {
        val clazz = field.type
        val list = obj as List<*>
        if (CopyOnWriteArrayList::class.java.isAssignableFrom(clazz)) {
            return CopyOnWriteArrayList(list)
        }
        if (LinkedList::class.java.isAssignableFrom(clazz)) {
            return LinkedList(list)
        }
        if (ArrayList::class.java.isAssignableFrom(clazz)) {
            return ArrayList(list)
        }
        if (Stack::class.java.isAssignableFrom(clazz)) {
            return Stack<Any>().apply {
                addAll(list)
            }
        }
        return list
    }

    override fun save(obj: Any): Any {
        return obj
    }

}

package top.iseason.bukkittemplate.config.type

import org.bukkit.configuration.MemorySection
import java.lang.reflect.Field
import java.util.concurrent.ConcurrentHashMap

/**
 * 涓€鑸琈ap銆丆oncurrentHashMap銆丩inkedHashMap銆丠ashMap
 */
object MapType : ConfigType {

    override fun checkType(clazz: Class<*>): Boolean {
        return Map::class.java.isAssignableFrom(clazz)
    }

    override fun read(obj: Any, field: Field): Any {
        val clazz = field.type
        val values = (obj as MemorySection).getValues(true)
        if (ConcurrentHashMap::class.java.isAssignableFrom(clazz)) {
            return ConcurrentHashMap(values)
        }
        if (LinkedHashMap::class.java.isAssignableFrom(clazz)) {
            return LinkedHashMap(values)
        }
        if (HashMap::class.java.isAssignableFrom(clazz)) {
            return HashMap(values)
        }
        return values
    }

    override fun save(obj: Any): Any {
        return obj
    }
}

package top.iseason.bukkittemplate.config.type

import java.lang.reflect.Field
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CopyOnWriteArraySet

/**
 * 涓€鑸琒et CopyOnWriteArraySet銆丆oncurrentHashMap.KeySetView銆丩inkedHashSet銆丠ashSet銆? */
object SetType : ConfigType {
    override fun checkType(clazz: Class<*>): Boolean {
        return Set::class.java.isAssignableFrom(clazz)
    }

    override fun read(obj: Any, field: Field): Any {
        val clazz = field.type
        val set = obj as Collection<*>
        if (CopyOnWriteArraySet::class.java.isAssignableFrom(clazz)) {
            return CopyOnWriteArraySet(set)
        }
        if (ConcurrentHashMap.KeySetView::class.java.isAssignableFrom(clazz)) {
            val newKeySet = ConcurrentHashMap.newKeySet<Any>(set.size)
            newKeySet.addAll(set)
            return newKeySet
        }
        if (LinkedHashSet::class.java.isAssignableFrom(clazz)) {
            return LinkedHashSet(set)
        }
        if (HashSet::class.java.isAssignableFrom(clazz)) {
            return HashSet(set)
        }
        return set.toHashSet()
    }

    override fun save(obj: Any): Any {
        return (obj as Collection<*>).toList()
    }


}

