/**
 * 鍙偣鍑荤殑Slot
 */
abstract class ClickSlot(
    /**
     * 鎸夐挳瀵瑰簲鐨勯粯璁ゅ浘鏍?     */
    open var rawItemStack: ItemStack? = null,
    /**
     * 浣嶄簬瀹瑰櫒涓殑浣嶇疆
     */
    override val index: Int = 0

) : BaseSlot {

    /**
     * 涓嶪nventory鐨処temStack鍚屾
     */
    override var itemStack: ItemStack?
        set(value) {
            baseInventory?.setItem(index, value)
        }
        get() {
            val item = baseInventory?.getItem(index)
            return if (item.checkAir()) rawItemStack
            else item
        }

    /**
     * 渚濇墭鐨処nventory
     */
    override var baseInventory: Inventory? = null

    /**
     * 鐐瑰嚮涔嬪墠
     */
    var onClick: (ClickSlot.(InventoryClickEvent) -> Unit)? = null

    /**
     * 鐐瑰嚮涔嬪悗
     */
    var onClicked: (ClickSlot.(InventoryClickEvent) -> Unit)? = null

    /**
     * 鏄惁寮傛鐐瑰嚮 鍙 onClicked 鏈夋晥
     */
    var asyncClick = false
}

/**
 * 鐐瑰嚮涔嬪悗
 */
fun <T : ClickSlot> T.onClicked(async: Boolean = false, action: (ClickSlot.(InventoryClickEvent) -> Unit)? = null): T {
    this.asyncClick = async
    this.onClicked = action
    return this
}

/**
 * 鐐瑰嚮涔嬪墠
 */
fun <T : ClickSlot> T.onClick(action: (ClickSlot.(InventoryClickEvent) -> Unit)? = null): T {
    this.onClick = action
    return this
}

/**
 * 璁剧疆渚濇墭鐨刄I
 */
fun Collection<ClickSlot>.setUI(ui: BaseUI) {
    ui.addSlots(*this.toTypedArray())
}

package top.iseason.bukkittemplate.ui.slot

import org.bukkit.entity.HumanEntity
import org.bukkit.inventory.ItemStack
import top.iseason.bukkittemplate.utils.bukkit.EntityUtils.giveItems
import top.iseason.bukkittemplate.utils.bukkit.ItemUtils.checkAir
import top.iseason.bukkittemplate.utils.other.submit

/**
 * 鐗╁搧妲斤紝鍙互杈撳叆鍜岃緭鍑虹墿鍝? * @param index 浣嶇疆绱㈠紩
 */
open class IOSlot(
    index: Int,
    //娌℃湁鐗╁搧鏃剁殑鍗犱綅绗?    placeholder: ItemStack?
) : ClickSlot(placeholder, index) {

    var placeholder: ItemStack?
        get() = rawItemStack
        set(value) {
            rawItemStack = value
        }

    /**
     * 涓嶪nventory鐨処temStack鍚屾,null鏃舵樉绀哄崰浣嶇
     */
    override var itemStack: ItemStack?
        set(value) {
            if (value == null) baseInventory?.setItem(index, placeholder)
            else baseInventory?.setItem(index, value)
        }
        get() {
            val item = baseInventory?.getItem(index)
            return if (item != null && !item.checkAir() && !item.isSimilar(placeholder)) item
            else null
        }

    /**
     * 杈撳叆杩囨护鍣紝this涓哄綋鍓嶆Ы,it涓鸿緭鍏ョ殑鐗╁搧
     * @return true 浠ュ厑璁歌緭鍏?     */
    var input: IOSlot.(ItemStack) -> Boolean = { true }

    /**
     * 杈撳嚭杩囨护鍣紝this涓哄綋鍓嶆Ы,it涓鸿緭鍑虹殑閮ㄥ垎
     * @return true 浠ュ厑璁歌緭鍑?     */
    var output: IOSlot.(ItemStack) -> Boolean = { true }

    /**
     * 褰撹緭鍏ョ墿鍝佹椂璋冪敤
     */
    var onInput: IOSlot.(ItemStack) -> Unit = {}

    /**
     * 杈撳叆鏃跺紓姝ヨ皟鐢紝鍙 onInput 鏈夋晥
     */
    var inputAsync = false

    /**
     * 褰撹緭鍑虹墿鍝佹椂璋冪敤
     */
    var onOutput: IOSlot.(ItemStack) -> Unit = {}

    /**
     * 杈撳嚭鏃跺紓姝ヨ皟鐢紝鍙 onOutput 鏈夋晥
     */
    var outputAsync = false

    /**
     * 灏嗙墿鍝佺粰鏌愪汉
     */
    fun eject(humanEntity: HumanEntity) {
        val itemStack = itemStack
        if (itemStack != null && output(this, itemStack)) {
            humanEntity.giveItems(itemStack)
            submit {
                onOutput(this@IOSlot, itemStack)
            }
            reset()
        }
    }

    fun ejectSilently(humanEntity: HumanEntity) {
        val itemStack = itemStack
        if (itemStack != null && output(this, itemStack)) {
            humanEntity.giveItems(itemStack)
            reset()
        }
    }

    override fun reset() {
        itemStack = null
    }


    override fun clone(index: Int): IOSlot = IOSlot(index, placeholder).also {
        it.input = input
        it.output = output
        it.onClick = onClick
        it.onClicked = onClicked
        it.onInput = onInput
        it.onOutput = onOutput
        it.asyncClick = asyncClick
    }
}

/**
 *  鏄惁涓婇攣,杩斿洖true涓婇攣
 */
fun <T : IOSlot> T.lockable(lockable: Boolean): T {
    inputAble(!lockable)
    outputAble(!lockable)
    return this
}

/**
