/**
 * 鍚堝苟鐩稿悓鐨処temStack,
 * @return 鍚堝苟鍓╀綑鐨処temStack,鏃犲墿浣欒繑鍥瀗ull
 */
fun ItemStack.merge(itemStack: ItemStack?): ItemStack? {
    val item = itemStack?.clone() ?: return null
    return if (isSimilar(item)) {
        val total = item.amount + amount
        val i = total - maxStackSize
        if (i <= 0) {
            amount = total
            null
        } else {
            item.amount = i
            amount = maxStackSize
            item
        }
    } else item
}

