import top.iseason.bukkittemplate.utils.other.submit

/**
 * bukkit鐨勭帺瀹惰緭鍏ュ伐鍏? */
object IOUtils {
    /**
     * 鎵撳紑涓€涓晫闈紝璁╃帺瀹惰緭鍏ョ墿鍝侊紝褰撶晫闈㈠叧闂椂鍥炶皟鏂规硶
     * @param inv 鎵撳紑鐨勭晫闈?     * @param async 鏄惁寮傛杩愯
     * @param timeout 瓒呮椂鏃堕棿锛屽崟浣峵ick
     * @param onFinish 鍥炶皟鏂规硶
     */
    fun Player.onItemInput(
        inv: Inventory = Bukkit.createInventory(null, 54, "&a璇疯緭鍏ョ墿鍝?.toColor()),
        async: Boolean = false,
        timeout: Long = 12000,
        onFinish: (Inventory) -> Unit
    ) {
        runSync {
            openInventory(inv)
        }
        var task: BukkitTask? = null
        var listener: EventUtils.FakeEventListener? = null
        listener = listen<InventoryCloseEvent> {
            if (inventory != inv) return@listen
            submit(async = async) {
                onFinish(inv)
            }
            task?.cancel()
            listener?.unregister()
        }
        task = submit(delay = timeout, async = async) {
            if (openInventory.topInventory == inv) {
                closeInventory()
            } else {
                onFinish(inv)
                listener.unregister()
            }
        }
    }
}

