package top.iseason.bukkittemplate.utils.other

import java.util.*

/**
 * 甯歌HashMap鍐峰嵈鏃堕棿琛紝閫傜敤浜庡ぇ澶氭暟鎯呭喌
 */
class CoolDown<T> {
    private val coolDownMap: HashMap<T, Long> = HashMap()

    /**
     * 妫€鏌ラ敭鍊兼槸鍚﹀湪鍐峰嵈涓?     * @param key 閿€?     * @param coolDown 鍐峰嵈鏃堕棿
     */
    fun check(key: T, coolDown: Long): Boolean {
        return EasyCoolDown.checkType(coolDownMap, key, coolDown)
    }

    fun remove(key: T) = coolDownMap.remove(key)
}

/**
 * 浣跨敤寮卞紩鐢ㄧ殑WeakHashMap鍐峰嵈鏃堕棿琛紝閫傜敤浜庝笉閲嶈銆佷笖鏃堕棿鐭殑鍐峰嵈
 */
class WeakCoolDown<T> {
    private val coolDownMap: WeakHashMap<T, Long> = WeakHashMap()

    /**
     * 妫€鏌ラ敭鍊兼槸鍚﹀湪鍐峰嵈涓?     * @param key 閿€?     * @param coolDown 鍐峰嵈鏃堕棿
     * @return true 琛ㄧず鍦ㄥ喎鍗?     */
    fun check(key: T, coolDown: Long): Boolean {
        return EasyCoolDown.checkType(coolDownMap, key, coolDown)
    }

    fun remove(key: T) = coolDownMap.remove(key)
}

/**
 * 瀵筍tring閿殑鍏ㄥ眬鍐峰嵈锛屽嵆寮€鍗崇敤锛屽急寮曠敤锛岄€傜敤浜庝笉澶噸瑕佺殑鍐峰嵈
 */
object EasyCoolDown {

    private val coolDownMap: MutableMap<String, Long> = Collections.synchronizedMap(WeakHashMap())

    /**
     * 妫€鏌ラ敭鍊兼槸鍚﹀湪鍐峰嵈涓?     * @param obj 閿€?     * @param coolDown 鍐峰嵈鏃堕棿
     * @return true 琛ㄧず鍦ㄥ喎鍗?     */
    fun check(obj: Any, coolDown: Long): Boolean {
        val key = obj.toString()
        return checkType(coolDownMap, key, coolDown)
    }

    // 妫€鏌ユ煇涓猰ap涓煇涓敭鍊兼槸鍚﹀湪鏌愪釜鍐峰嵈鏃堕棿鍐?    fun <T> checkType(map: MutableMap<T, Long>, obj: T, coolDown: Long): Boolean {
        val lastTime = map[obj]
        val current = System.currentTimeMillis()
        if (lastTime == null) {
            map[obj] = current
            return false
        }
        if (current - lastTime <= coolDown) return true
        map[obj] = current
        return false
    }
}

package top.iseason.bukkittemplate.utils.other

import top.iseason.bukkittemplate.debug.warn

/**
 * 鎬ц兘娴嬭瘯宸ュ叿
 */
@Suppress("MemberVisibilityCanBePrivate", "unused")
object LagCatcher {

    private val startTimesMap = mutableMapOf<String, Long>()

    /**
     *  瀵逛换鍔¤繘琛屾€ц兘娴嬭瘯锛岃緭鍑轰换鍔¤€楁椂
     *
     *  @param name 浠诲姟鍚嶇О
     *  @param cycles 寰幆浠诲姟娆℃暟
     *  @param task 浠诲姟
     */
    fun performanceTest(name: String, cycles: Int, task: () -> Unit) {
        start(name)
        for (i in 0 until cycles) {
            task()
        }
        end(name)
    }


    /**
     *  妫€娴嬭浠诲姟鏄惁瓒呰繃 checkValue 姣, 瓒呰繃灏辫緭鍑鸿鍛婁俊鎭?     *
     *  @param name 浠诲姟鍚嶇О
     *  @param checkValue 妫€娴嬪€?     *  @param task 浠诲姟
     */
    fun performanceCheck(name: String, checkValue: Int = 10, task: () -> Unit) {
        start(name)

        task()

        end(name, checkValue)
    }

    private fun start(name: String) {
        startTimesMap[name] = System.currentTimeMillis()
    }

    private fun end(name: String, checkValue: Int = 0) {
        val duration = System.currentTimeMillis() - (startTimesMap[name] ?: error("$name 鏈紑鍚€ц兘鐩戞帶"))
        startTimesMap.remove(name)

        if (duration >= checkValue) {
            warn("浠诲姟銆?name銆忚€楁椂 $duration ms")
        }
    }
}

