@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package top.iseason.bukkittemplate.utils.other

import java.security.SecureRandom
import kotlin.math.abs

/**
 * 瀹夊叏闅忔満鏁板伐鍏凤紝姣旀櫘閫氶殢鏈烘洿闅忔満锛屼絾鐢ㄦ椂涔熶細澶氫竴浜? */
object RandomUtils {
    private val SECURE_RANDOM = SecureRandom()

    /**
     * 鑾峰彇瀹夊叏鐨勯殢鏈哄皬鏁?Double)锛岃寖鍥碵start,end) 榛樿[0.0D,1.0D)
     */
    fun getDouble(start: Double = 0.0, end: Double = 1.0) = start + SECURE_RANDOM.nextDouble() * (end - start)

    /**
     * 鑾峰彇瀹夊叏鐨勯殢鏈烘暣鏁帮紝鑼冨洿[start,end] 榛樿[0,Int.MAX_VALUE)
     */
    fun getInteger(start: Int = 0, end: Int = Int.MAX_VALUE - 1) = start + SECURE_RANDOM.nextInt(end - start + 1)

    /**
     * 鑾峰彇瀹夊叏鐨勯殢鏈哄竷灏斿€?     */
    fun getBoolean() = SECURE_RANDOM.nextBoolean()

    /**
     * 鑾峰彇瀹夊叏鐨勯殢鏈哄皬鏁?Float)锛岃寖鍥碵start,end) 榛樿[0.0F,1.0F)
     */
    fun getFloat(start: Float = 0F, end: Float = 1F) = start + SECURE_RANDOM.nextFloat() * (end - start)

    /**
     * 鑾峰彇瀹夊叏鐨勯殢鏈洪暱鏁村瀷
     */
    fun getLong() = SECURE_RANDOM.nextLong()

    /**
     * 缁欏畾鍒ゆ柇缁欏畾姒傜巼鏄惁鐢熸晥
     * @return 婊¤冻姒傜巼杩斿洖false,鍚︿箣杩斿洖true
     */
    fun checkPercentage(percent: Int) = getDouble(end = 100.0) >= percent

    /**
     * 缁欏畾鍒ゆ柇缁欏畾姒傜巼鏄惁鐢熸晥
     * @return 婊¤冻姒傜巼杩斿洖false,鍚︿箣杩斿洖true
     */
    fun checkPercentage(percent: Double) = getDouble(end = 100.0) >= percent

    /**
     * 鑾峰彇浠?涓哄绉拌酱锛岃寖鍥翠负(-1,1)鐨勯珮鏂垎甯?     */
    fun getGaussian() = SECURE_RANDOM.nextGaussian()

    /**
     * 鑼冨洿鍖洪棿鍐匸start,end]鐨勬鎬佸垎甯冿紝涓績杞翠负鍖洪棿涓績
     */
    fun getGaussian(start: Double, end: Double): Double {
        val gaussian = getGaussian()
        val odd = if (abs(gaussian) < 3) gaussian / 3.00 else 1.00
        val half = (start + end) / 2.00
        return odd * (end - half) + half
    }

    /**
     * 鍔犳潈闅忔満鍖洪棿
     * @return 閫変腑鐨勬潈閲嶅簭鍙?     */
    fun getWeighted(weights: Iterable<Double>): Int {
        val sum = weights.sum()
        val random = getDouble(0.0, sum)
        var temp = 0.0
        weights.forEachIndexed { index, i ->
            temp += i
            if (random <= temp) return index
        }
        return 0
    }

    //鏍规嵁绛夌骇璁＄畻鏃惰繍闅忔満鍚庣殑鍊嶇巼
    fun calculateFortune(level: Int): Int {
        if (level <= 0) throw IllegalArgumentException("level can not <= 0")
        var temp = 2.0 / (level + 2)
        val otherRate = (1 - temp) / level
        val random = SECURE_RANDOM.nextDouble()
        for (n in 1..level + 1) {
            if (random <= temp) return n
            temp += otherRate
        }
        return 1
    }
}

package top.iseason.bukkittemplate.utils.other

import org.bukkit.Bukkit
import org.bukkit.scheduler.BukkitTask
import top.iseason.bukkittemplate.BukkitTemplate
import java.util.concurrent.CompletableFuture

/**
 * 鎻愪氦涓€涓?bukkit runnable浠诲姟
 * @param delay 寤惰繜 鍗曚綅tick
 * @param period 寰幆鍛ㄦ湡 鍗曚綅tick
 * @param async 鏄惁寮傛
 * @param task 浣犵殑浠诲姟
 */
fun submit(
    delay: Long = 0,
    period: Long = 0,
    async: Boolean = false,
    task: Runnable
): BukkitTask {
    check(delay >= 0) { "delay must grater than 0" }
    check(period >= 0) { "period must grater than 0" }
    return if (async) {
        if (period > 0) {
            Bukkit.getScheduler().runTaskTimerAsynchronously(BukkitTemplate.getPlugin(), task, delay, period)
        } else {
            Bukkit.getScheduler().runTaskLaterAsynchronously(BukkitTemplate.getPlugin(), task, delay)
        }
    } else {
        if (period > 0) {
            Bukkit.getScheduler().runTaskTimer(BukkitTemplate.getPlugin(), task, delay, period)
        } else {
            Bukkit.getScheduler().runTaskLater(BukkitTemplate.getPlugin(), task, delay)
        }
    }
}

/**
 * 鍦ㄤ富绾跨▼杩愯浠诲姟(浣跨敤BukkitRunnable)
 */
fun runSync(task: Runnable) = Bukkit.getScheduler().runTask(BukkitTemplate.getPlugin(), task)

/**
 * 鍦ㄥ紓姝ョ嚎绋嬭繍琛屼换鍔? */
fun runAsync(task: Runnable) {
    CompletableFuture.runAsync(task)
}

