fun Map<Int, Map<ItemStat<*, *>, String>>.getLevelMap(level: Int): Map<ItemStat<*, *>, String> {
    var attributes = emptyMap<ItemStat<*, *>, String>()
    for ((l, dataMap) in this) {
        if (l > level) break
        attributes = dataMap
    }
    return attributes
}

